/* startup_stm32f405.s
 * Minimal Cortex-M4 startup for STM32F405 (QEMU netduinoplus2 / real HW).
 * Generated by StaTable Eclipse Installer v0.1.0
 *
 * Not for production. Adjust vector table and clock init for your board.
 */
.syntax unified
.cpu cortex-m4
.thumb

.section .isr_vector,"a",%progbits
.global g_pfnVectors
.type g_pfnVectors, %object
g_pfnVectors:
    .word _estack
    .word Reset_Handler
    .word NMI_Handler
    .word HardFault_Handler
    .word MemManage_Handler
    .word BusFault_Handler
    .word UsageFault_Handler
    .word 0
    .word 0
    .word 0
    .word 0
    .word SVC_Handler
    .word DebugMon_Handler
    .word 0
    .word PendSV_Handler
    .word SysTick_Handler
    /* External IRQs (STM32F405: up to 82) */
    .rept 82
    .word Default_Handler
    .endr
.size g_pfnVectors, . - g_pfnVectors

.text

.thumb_func
.global Reset_Handler
.type Reset_Handler, %function
Reset_Handler:
    /* --- Copy .data from FLASH to RAM --- */
    ldr r0, =_sdata
    ldr r1, =_edata
    ldr r2, =_sidata
CopyDataLoop:
    cmp r0, r1
    bcs CopyDataDone
    ldr r3, [r2], #4
    str r3, [r0], #4
    b CopyDataLoop
CopyDataDone:

    /* --- Zero .bss --- */
    ldr r0, =_sbss
    ldr r1, =_ebss
    movs r2, #0
ZeroBssLoop:
    cmp r0, r1
    bcs ZeroBssDone
    str r2, [r0], #4
    b ZeroBssLoop
ZeroBssDone:

    bl main
    b .

.thumb_func
.global Default_Handler
.type Default_Handler, %function
Default_Handler:
    b .

/* Weak aliases: user can override any of these */
.weak NMI_Handler
.thumb_set NMI_Handler, Default_Handler
.weak HardFault_Handler
.thumb_set HardFault_Handler, Default_Handler
.weak MemManage_Handler
.thumb_set MemManage_Handler, Default_Handler
.weak BusFault_Handler
.thumb_set BusFault_Handler, Default_Handler
.weak UsageFault_Handler
.thumb_set UsageFault_Handler, Default_Handler
.weak SVC_Handler
.thumb_set SVC_Handler, Default_Handler
.weak DebugMon_Handler
.thumb_set DebugMon_Handler, Default_Handler
.weak PendSV_Handler
.thumb_set PendSV_Handler, Default_Handler
.weak SysTick_Handler
.thumb_set SysTick_Handler, Default_Handler
